def interpreter_abi() -> str:
    """
    Returns the ABI tag of the running interpreter.

    This typically acts as the :attr:`~Tag.abi` tag of a tag triple.

    On CPython, the ABI is the interpreter name and version joined together
    (e.g. ``"cp310"``). On other interpreters, the ABI is derived from the
    interpreter's extension suffix (e.g. ``"pypy310_pp73"``).

    .. versionadded:: 26.4
    """
    if interpreter_name() == "cp":
        return f"cp{_version_nodot(sys.version_info[:2])}"
    else:
        return next(_generic_abi())
